import itertools
import networkx as nx

def has_non_periodic_path(S, k):
    adj = {t: [] for t in S}
    for t in S:
        for t_next in S:
            if t[1:] == t_next[:-1]:
                adj[t].append(t_next)

    G = nx.DiGraph()
    for t in S:
        for t_next in adj[t]:
            G.add_edge(t, t_next)

    sccs = list(nx.strongly_connected_components(G))
    for scc in sccs:
        if len(scc) < 1: continue
        subgraph = G.subgraph(scc)
        for node in scc:
            if subgraph.out_degree(node) >= 2:
                return True
    return False

def find_min_m(k):
    # Use values from {0, 1}
    all_tuples = list(itertools.product(range(2), repeat=k))
    # If m is too large, we might need more values. But let's try 2 first.
    for m in range(1, 2**k + 1):
        for S in itertools.combinations(all_tuples, m):
            if has_non_periodic_path(S, k):
                return m
    return None

print(f"k=1: {find_min_m(1)}")
print(f"k=2: {find_min_m(2)}")
print(f"k=3: {find_min_m(3)}")
